private void OnCollisionStay(Collision collision)
{
    Rigidbody otherRigidbody = collision.gameObject.GetComponent<Rigidbody>(); //get other object

    if (otherRigidbody != null) //check for rigidbodies
    {
        otherRigidbody.linearVelocity = MovementDirection.normalized * movementSpeed; //add direction and speed
    }
}

void Update()
{
  Vector3 currentPosition = transform.position;

    if (OpenDoor == true)
    {
        if (OpenAmount < 1.5)
        {
            OpenAmount = (OpenAmount + Time.deltaTime);
        }
    }
    else
    {
        if (OpenAmount > 0)
        {
          OpenAmount = (OpenAmount - Time.deltaTime);
        }
    }

    transform.position = new Vector3(transform.position.x, transform.position.y, StartingPosition + OpenAmount);

    OpenAmount = Mathf.Clamp(OpenAmount, 0f, 1.5f);
}
}

private void OnCollisionEnter(Collision other)
{
   if (Cooldown <= 0 && !Broken)
   {
       Enemy EnemyCollider = other.gameObject.GetComponent<Enemy>();

       if (EnemyCollider != null)
       {
         EnemyCollider.ZHealth = EnemyCollider.ZHealth - MeleeDamage;
         EnemyCollider.ZDamage();
         if (Breakable)
         {
             Durability = Durability - 1;
         }
         Cooldown = AttackSpeed;
         if (Durability == 0)
         {
             Break();
         }
       }
   }
}

private void OnCollisionEnter(Collision collision)
{
   if (collision.gameObject.CompareTag("Enemy"))
   {
       EnemyScript = collision.gameObject.GetComponent<Enemy>();
       EnemyScript.ZHealth = EnemyScript.ZHealth - 1;
       EnemyScript.ZDamage();
   }


   if (!collision.gameObject.CompareTag("Weapon"))
   {
       Destroy(gameObject);
   }

}

void Dying()
{
    if (HoldingObject == true)
    {
        DeathSound.Play();
        Instantiate(heldObject, DropPos, gameObject.transform.rotation);
        HoldingObject = false;
    }
    Debug.Log("Enemy is ded");
    if (EnemyDeathTimer > 0)
    {
        EnemyDeathTimer -= Time.deltaTime;
    }
    else
    {
        if (DeathEffect != null)
        {
            Instantiate(DeathEffect, DropPos, transform.rotation);
        }
        Destroy(gameObject);
    }
}

