void OnTriggerStay(Collider other)
{
        if (other.GetComponent<PlayerController>() != null)
        {
            player.transform.position = new Vector3(player.transform.position.x + Direction.x * (Speed/100), player.transform.position.y + Direction.y * (Speed/100), player.transform.position.z + Direction.z * (Speed/100));
        }

        if (other.GetComponent<AuBullet>() != null)
        {
            bullet = other.GetComponent<AuBullet>();
            bullet.BulletDirection = Direction;
            bullet.BulletSpeed = Speed;
        }
    }

void Move()
    {
        if (MoveTimer > 0)
        {
            Pos.x += Time.deltaTime * ActualRange.x;     
            Pos.y += Time.deltaTime * ActualRange.y;     
            Pos.z += Time.deltaTime * ActualRange.z;     

            MoveTimer -= Time.deltaTime;
        }
        Target.transform.position = new Vector3(TargetStartPos.x + Pos.x, TargetStartPos.y + Pos.y, TargetStartPos.z + Pos.z);
    }

    void summon()
    {
        for (int i = 0; i < SummonAmount; i++)
        {
            Instantiate(Target, TargetPos, Quaternion.identity);
        }

        LeverType = TargetType.empty;
    }
